import { CATEGORIES, type Category, type Difficulty, type QuestionRecord } from "@/lib/domain";

interface SeedText {
  prompt: string;
  answer: string;
  aliases?: string[];
  explanation: string;
  source?: string | null;
}

let counter = 0;

function q(category: Category, difficulty: Difficulty, en: SeedText, tr: SeedText): QuestionRecord {
  counter += 1;
  const id = `q${String(counter).padStart(3, "0")}`;
  return {
    id,
    category,
    difficulty,
    approved: true,
    translations: {
      en: {
        prompt: en.prompt,
        answer: en.answer,
        aliases: en.aliases ?? [],
        explanation: en.explanation,
        source: en.source ?? null,
        language: "en",
      },
      tr: {
        prompt: tr.prompt,
        answer: tr.answer,
        aliases: tr.aliases ?? [],
        explanation: tr.explanation,
        source: tr.source ?? en.source ?? null,
        language: "tr",
      },
    },
  };
}

